CREATE TABLE production_release_attempts (version_id TEXT NOT NULL, candidate_commit TEXT NOT NULL, manifest_id TEXT NOT NULL, attempt INTEGER NOT NULL CHECK (attempt > 0), idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'succeeded', 'failed')), started_at TEXT NOT NULL, completed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, failure_fingerprint TEXT, PRIMARY KEY (version_id, candidate_commit, manifest_id, attempt));
CREATE TABLE production_release_targets (version_id TEXT NOT NULL, candidate_commit TEXT NOT NULL, manifest_id TEXT NOT NULL, platform TEXT NOT NULL, app_id TEXT NOT NULL, attempt INTEGER NOT NULL CHECK (attempt > 0), stage TEXT NOT NULL CHECK (stage IN ('preflight', 'upload', 'switch', 'health', 'readback', 'test', 'archive', 'processing', 'review_submit', 'review_wait', 'release', 'live_readback')), status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'succeeded', 'failed')), external_request_id TEXT, upload_id TEXT, review_id TEXT, live_id TEXT, sanitized_observed_evidence TEXT CHECK (sanitized_observed_evidence IS NULL OR json_valid(sanitized_observed_evidence)), failure_fingerprint TEXT, started_at TEXT NOT NULL, completed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (version_id, candidate_commit, manifest_id, platform, app_id, attempt));
CREATE INDEX idx_production_release_targets_latest ON production_release_targets (version_id, candidate_commit, manifest_id, platform, app_id, attempt DESC);
CREATE INDEX idx_production_release_targets_reusable_success ON production_release_targets (version_id, candidate_commit, manifest_id, platform, app_id, attempt DESC) WHERE status = 'succeeded' AND stage = 'live_readback';
